:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #28352d;
  background: #f4ead7;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #f4ead7;
  background-image: radial-gradient(#dfcfb3 1px, transparent 1px);
  background-size: 16px 16px;
}

.card {
  width: min(100%, 500px);
  padding: 32px;
  border: 3px solid #28352d;
  border-radius: 12px;
  background: #fffaf0;
  box-shadow: 8px 8px 0 #c6a86a;
}

.pixel-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin-bottom: 20px;
  border: 2px solid #28352d;
  background: #e6a25b;
  color: #28352d;
  font-size: 27px;
}

.eyebrow {
  margin: 0 0 6px;
  color: #52745c;
  font-size: 0.875rem;
  font-weight: 750;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.7rem); line-height: 1.1; }
.intro { margin: 12px 0 28px; color: #566158; line-height: 1.5; }

.fields { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.field { display: grid; gap: 8px; }
label { font-weight: 700; }

input, select, button {
  min-height: 48px;
  width: 100%;
  border: 2px solid #28352d;
  border-radius: 6px;
  color: #28352d;
  font: inherit;
}

input, select { padding: 10px 12px; background: #fff; }
input:focus-visible, select:focus-visible, button:focus-visible { outline: 3px solid #52745c; outline-offset: 3px; }

button {
  margin-top: 20px;
  padding: 10px 16px;
  background: #52745c;
  color: #fffaf0;
  font-weight: 750;
  cursor: pointer;
  transition: background-color 120ms ease, transform 120ms ease, box-shadow 120ms ease;
  box-shadow: 0 3px 0 #28352d;
}
button:hover { background: #3f6149; }
button:active { transform: translateY(2px); box-shadow: 0 1px 0 #28352d; }

.results { margin-top: 28px; padding-top: 22px; border-top: 2px dashed #c6a86a; }
h2 { margin: 0 0 12px; font-size: 1.1rem; }
#result-list { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
#result-list li { display: flex; justify-content: space-between; gap: 12px; padding: 10px 12px; border-radius: 5px; background: #edf1e8; }
.result-value { font-weight: 750; font-variant-numeric: tabular-nums; }
.ratio-note { margin: 20px 0 0; color: #566158; font-size: 0.875rem; text-align: center; }

@media (max-width: 420px) {
  .card { padding: 24px 20px; }
  .fields { gap: 12px; }
}

const units = [
  { key: "cups", label: "Cups", factor: 240 },
  { key: "tablespoons", label: "Tablespoons", factor: 15 },
  { key: "teaspoons", label: "Teaspoons", factor: 5 },
  { key: "millilitres", label: "Millilitres", factor: 1 }
];

const form = document.querySelector("#converter-form");
const amountInput = document.querySelector("#amount");
const unitSelect = document.querySelector("#unit");
const resultList = document.querySelector("#result-list");

function convert() {
  const amount = Number(amountInput.value);
  const source = units.find((unit) => unit.key === unitSelect.value);
  resultList.replaceChildren();

  if (!Number.isFinite(amount) || amount < 0 || amountInput.value === "") {
    const item = document.createElement("li");
    item.textContent = "Enter a non-negative amount to convert.";
    resultList.append(item);
    return;
  }

  const millilitres = amount * source.factor;
  units.filter((unit) => unit.key !== source.key).forEach((unit) => {
    const item = document.createElement("li");
    const label = document.createElement("span");
    const value = document.createElement("span");
    label.textContent = unit.label;
    value.className = "result-value";
    value.textContent = `${(millilitres / unit.factor).toFixed(1)} ${unit.key === "millilitres" ? "ml" : unit.key === "tablespoons" ? "tbsp" : unit.key === "teaspoons" ? "tsp" : "cups"}`;
    item.append(label, value);
    resultList.append(item);
  });
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  convert();
});
amountInput.addEventListener("input", convert);
unitSelect.addEventListener("change", convert);
convert();
